<?php use App\Core\Authorization;use App\Core\Csrf;$canManage=Authorization::allows('insurance.manage');$canClaim=Authorization::allows('insurance.claims'); ?>
<div class="page-heading"><div><p class="eyebrow"><?=e($policy['holder_type'])?> insurance · <?=e($policy['reference_no'])?></p><h1><?=e($policy['holder_name'])?></h1><p><?=e($policy['provider'])?> · <?=e($policy['policy_no'])?></p></div><a class="button" href="<?=e(url('/insurance'))?>">Back to insurance</a></div><div class="grid three insurance-summary"><article class="stat-card"><span>Coverage period</span><strong class="date-range"><?=e($policy['coverage_start'])?></strong><small>through <?=e($policy['coverage_end'])?></small></article><article class="stat-card"><span>Premium</span><strong><?=is_null($policy['premium_amount'])?'—':'PHP '.number_format((float)$policy['premium_amount'],2)?></strong><small><?=e($policy['plan_name']?:'Plan not specified')?></small></article><article class="stat-card"><span>Coverage amount</span><strong><?=is_null($policy['coverage_amount'])?'—':'PHP '.number_format((float)$policy['coverage_amount'],2)?></strong><small><span class="badge"><?=e($policy['status'])?></span></small></article></div>
<div class="detail-grid insurance-actions"><?php if($canClaim&&$policy['status']!=='cancelled'):?><section class="card form-section"><h2>Record claim</h2><form method="post" action="<?=e(url('/insurance/'.$policy['id'].'/claims'))?>" class="stack-form"><?=Csrf::field()?><div class="grid two"><label>Claim number<input required name="claim_no"></label><label>Filed on<input required type="date" name="filed_on" value="<?=e(date('Y-m-d'))?>"></label><label>Incident date<input type="date" name="incident_date"></label><label>Claim amount<input required type="number" min="0.01" step="0.01" name="claim_amount"></label></div><label>Remarks<textarea name="remarks" rows="2"></textarea></label><button class="button primary">Record claim</button></form></section><?php endif;?><?php if($canManage):?><section class="card form-section"><h2>Policy status</h2><p><?=nl2br(e($policy['remarks']?:'No policy remarks.'))?></p><form method="post" action="<?=e(url('/insurance/'.$policy['id'].'/status'))?>" class="stack-form"><?=Csrf::field()?><label>Status<select name="status"><?php foreach(['pending','active','expired','cancelled'] as $x):?><option value="<?=$x?>" <?=$policy['status']===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></label><button class="button">Update status</button></form></section><?php endif;?></div>
<section class="card table-card section-card"><div class="table-heading"><div><h2>Claims</h2><small><?=count($claims)?> recorded claims</small></div></div><table><thead><tr><th>Claim</th><th>Dates</th><th>Claimed</th><th>Approved</th><th>Status</th><th>Recorded by</th><th></th></tr></thead><tbody><?php foreach($claims as $c):?><tr><td><strong><?=e($c['claim_no'])?></strong><br><small><?=e($c['remarks'])?></small></td><td>Filed <?=e($c['filed_on'])?><br><small>Incident <?=e($c['incident_date']?:'—')?></small></td><td>PHP <?=number_format((float)$c['claim_amount'],2)?></td><td><?=is_null($c['approved_amount'])?'—':'PHP '.number_format((float)$c['approved_amount'],2)?></td><td><span class="badge"><?=e(str_replace('_',' ',$c['status']))?></span></td><td><?=e($c['recorder'])?></td><td><?php if($canClaim):?><form method="post" action="<?=e(url('/insurance/'.$policy['id'].'/claims/'.$c['id']))?>" class="claim-update"><?=Csrf::field()?><select name="status"><?php foreach(['submitted','under_review','approved','rejected','paid'] as $x):?><option value="<?=$x?>" <?=$c['status']===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach;?></select><input type="number" min="0" step="0.01" name="approved_amount" value="<?=e((string)$c['approved_amount'])?>" placeholder="Approved amount"><button class="button small">Update</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$claims):?><tr><td colspan="7" class="empty">No claims recorded for this policy.</td></tr><?php endif;?></tbody></table></section>
